window.ME_DATA = window.ME_DATA || {};
window.ME_DATA["y8-me"] = [
 {
  id:"l1", lesson:1, title:"Responsibilities & Duties Toward Peers", unit:"Unit 1: Character & Morality", art:"peers",
  dna:"Think of a time a friend or classmate helped you without being asked. Write down what they did and how it made you feel. What does this tell you about what peers owe each other?",
  dnaQs:["What did your friend or classmate do to help you, without being asked?","How did it make you feel?","What does this tell you about what peers owe each other?"],
  dnaHint:"A good answer describes one specific act (for example, helping with work or including you at lunch), names a feeling (relieved, welcome, grateful), and links it to a duty peers have, such as support, kindness or inclusion.",
  intentions:["Understand the key responsibilities and duties individuals have for their peers.","Explore what peer responsibility looks like in everyday school life.","Apply understanding of peer responsibility to a real scenario."],
  criteria:["I can explain key responsibilities and duties individuals have for their peers.","I can give examples of peer responsibility in daily life.","I can apply this understanding to judge a real scenario."],
  concept:{key:"Relationships", related:"Responsibility, Community", soi:"Individuals build stronger peer relationships by understanding and fulfilling their responsibilities to one another.", context:"Identities and Relationships — exploring how individuals form and maintain healthy relationships with peers.", uae:"UAE national values of cooperation (ta'awun) and community; links to English (narrative/reflective writing)."},
  words:[["Peer","A person of the same age or social group as oneself, such as a classmate."],["Responsibility","A duty to deal with or take care of something or someone."],["Loyalty","Being faithful and supportive to a friend or group."],["Support","Help or encouragement given to another person."],["Accountability","Being answerable for one's own actions and their effects on others."],["Inclusion","Making sure everyone feels and is treated as a valued member of a group."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion B — Investigating", steps:["Choose ONE real peer-support programme (e.g. a school buddy system, peer mentoring, peer mediation).","Research it using at least two reliable sources.","Record: how it works, and what responsibility it asks peers to take for one another.","Note one benefit this kind of programme could bring to a school community."], prompts:["The programme I chose and my two sources","How it works","The responsibility it asks peers to take for one another","One benefit it could bring to a school community"], success:"Good examples include peer mentoring schemes (older students supporting younger ones), buddy systems for new students, and peer mediation for resolving minor conflicts. Strong answers explain specifically what responsibility peers take on (e.g. listening without judgement, checking in regularly) rather than describing the scheme only in general terms. For the top band, use two credible sources and evaluate a genuine benefit to the school community."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"Omar noticed that Zayed, a new student, was sitting alone at lunch every day. Omar's friends wanted to save him a seat at their table, but Omar wasn't sure if it was really 'his job' to include someone he barely knew.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), explain what responsibility, if any, Omar has toward Zayed.","Use at least THREE words from the Word Bank (e.g. peer, responsibility, inclusion) accurately.","Conclude with what you think Omar should do, and why."], model:"Omar has a general responsibility, as a peer, to help create an inclusive environment, even though Zayed is not yet a close friend. Responsibility toward peers does not only apply to existing friendships — it includes noticing when someone is excluded and making a small effort to help them feel welcome. This does not mean Omar must become Zayed's best friend, but a simple act of inclusion, like inviting him to sit with the group, reflects a basic peer responsibility. I think Omar should invite Zayed to join them, because a small act of inclusion can make a big difference to someone new.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; conclusion is well-justified."]], starters:["Omar's responsibility is ___ because ___.","As a peer, Omar has a duty to ___.","This does not mean Omar must ___, but ___.","I think he should ___ because ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Design a Peer Support Scheme", steps:["In groups of 3–4, design a simple peer-support scheme for your year group (e.g. a buddy system, a lunchtime welcome club, a peer listening scheme).","Explain what responsibility peers would take on in your scheme.","Identify one challenge your scheme might face (e.g. shyness, time), and how you would address it.","Design a simple poster or flyer to promote your scheme.","Present your scheme to the class in a 3-minute pitch. Use Word Bank vocabulary in your presentation."], rubric:[["1–2","Scheme lacks clear peer responsibility; no challenge identified."],["3–4","Basic scheme with limited detail; challenge named but not addressed."],["5–6","Clear scheme with defined peer responsibility; challenge identified and addressed."],["7–8","Well-designed, realistic scheme; peer responsibility and challenge response are thoughtful and convincing."]]},
  game:{type:"sort", title:"Responsible Peer or Not?", prompt:"Sort each action: does it show responsibility toward a peer, or not?", bins:["Shows peer responsibility","Does not show peer responsibility"], items:[["Inviting a new student to sit with your group at lunch",0],["Checking in on a classmate who seems upset",0],["Telling a trusted adult when a peer is being treated unkindly",0],["Ignoring someone who is always left out because they are not your friend",1],["Laughing along when a classmate is being mocked",1],["Listening to a peer without judging them",0],["Blaming a classmate for your own mistake",1],["Including everyone when choosing groups for a game",0]]},
  quiz:[["What is a peer?",["A person of the same age or social group as you, such as a classmate","An adult who is in charge of you","A member of your family"],0],["What does 'inclusion' mean?",["Choosing only your closest friends","Keeping a group small and private","Making sure everyone feels and is treated as a valued member of a group"],2],["What does 'accountability' mean?",["Being good at maths","Being answerable for your own actions and their effects on others","Always agreeing with your friends"],1],["Does peer responsibility mean you must be best friends with everyone?",["Yes, you must befriend every classmate","No, it means basic decency and inclusion toward all peers","No, it only applies to your close friends"],1],["In the extract, what is a responsible thing Omar could do for Zayed?",["Invite him to sit with the group","Wait until Zayed makes friends by himself","Tell his friends not to save a seat"],0],["Reporting unkindness toward a peer to a trusted adult is best described as…",["Snitching","None of your business","A responsible way to protect a peer"],2],["Which is an example of a real peer-support programme?",["A homework deadline","A school timetable","A school buddy system for new students"],2],["Which UAE value does this lesson link to?",["Competition between classmates","Cooperation (ta'awun) and community","Keeping to yourself"],1]],
  exit:"Write ONE small action you could take this week to show responsibility toward a peer.",
  copy:{facts:["Peers have responsibilities to one another, such as kindness, honesty, inclusion and support.","Peer responsibility applies to all peers, not only close friends — but it means basic decency, not having to befriend everyone.","Small acts of inclusion, like inviting someone to sit with you, can make a big difference to someone new."]},
  next:"Next lesson: we continue Unit 1 by exploring responsibilities and duties within family life."
 },
 {
  id:"l2", lesson:2, title:"Responsibilities as Sons and Daughters", unit:"Unit 1: Character & Morality", art:"family",
  dna:"Recap: in one sentence, name one responsibility peers have toward each other from last lesson. Now think: without naming anyone specific, write down ONE small task or responsibility that is common for children to have at home (e.g. tidying a room, helping a sibling).",
  dnaQs:["Name one responsibility peers have toward each other (from last lesson).","Name ONE task or responsibility that is common for children to have at home."],
  dnaHint:"For the recap, you could say peers have a responsibility to include others or support a classmate. For the home task, think of examples like tidying your room, helping a younger sibling or helping with household jobs. You do not need to name anyone.",
  intentions:["Understand key responsibilities and duties as a son or daughter in family life.","Explore how family responsibilities can vary between different families and cultures.","Reflect on how family responsibilities contribute to daily life."],
  criteria:["I can describe key responsibilities and duties as a son or daughter.","I can explain how family responsibilities can differ between families and cultures.","I can reflect on how family responsibilities contribute to daily life."],
  concept:{key:"Relationships", related:"Responsibility, Culture", soi:"Fulfilling responsibilities within family life strengthens relationships and contributes to a well-functioning household.", context:"Identities and Relationships — exploring roles and relationships within the family.", uae:"The strong emphasis on family (usra) and filial duty in UAE culture and Islamic values; links to Individuals & Societies."},
  words:[["Duty","An action a person is morally or socially expected to carry out."],["Family","A group of people related by blood, marriage or close bonds, often living together."],["Role","The part a person plays within a family or group, along with its expectations."],["Respect","Recognising the worth of someone, including their position within a family."],["Contribution","Something a person gives or does to help a shared effort, such as a household."],["Household","A family or group of people living together in one home."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion A — Knowing and Understanding", steps:["Choose ONE culture or society (can include the UAE) and research typical expectations for children's responsibilities within the family.","Research using at least two respectful, reliable sources.","Record: what responsibilities are commonly expected, and why they matter to that family/community.","Note one way these expectations might be similar to or different from another culture you know of.","Keep descriptions respectful and avoid generalising about all families in a culture."], prompts:["The culture or society I chose and my two sources","Responsibilities commonly expected of children","Why these responsibilities matter to that family/community","One similarity or difference with another culture"], success:"Good examples: many cultures expect older children to help care for younger siblings; some emphasise contributing financially once working age; many cultures emphasise caring for elderly parents as adults. Strong answers avoid stereotyping (e.g. “all families in X do Y”) and instead describe common expectations while recognising diversity within any culture — say “many families” rather than “all families”. For the top band, use two credible sources and make a thoughtful comparison."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"Layla wants to go to a friend's birthday party, but it's her turn to help her grandmother with weekly grocery shopping. Her brother offers to swap responsibilities with her this one time.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), explain why family responsibilities matter, using Layla's situation as an example.","Use at least THREE words from the Word Bank (e.g. duty, contribution, respect) accurately.","Explain whether you think swapping responsibilities occasionally is a reasonable solution, and why."], model:"Family responsibilities matter because they help a household function smoothly and show respect for other family members' time and needs, as seen in Layla's duty to help her grandmother. Her contribution isn't just a chore — it reflects care for a family member who relies on her. Swapping responsibilities occasionally, as her brother offers, is a reasonable solution because the underlying duty is still met, just carried out by a different family member, showing flexibility rather than avoiding the responsibility altogether.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; judgement on swapping is well-justified."]], starters:["Family responsibilities matter because ___.","Layla's duty to help her grandmother shows ___.","Swapping responsibilities occasionally is / is not reasonable because ___.","Her contribution is more than a chore because ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Family Roles Poster", steps:["In groups of 3–4, you will be given TWO fictional family profiles with different structures and circumstances.","For each fictional family, identify 2–3 likely responsibilities a child might have, and explain why.","Compare the two families: what's similar, and what's different, about their responsibilities?","Design a poster presenting both families' responsibilities respectfully and without judgement.","Present your poster to the class in a 3-minute pitch. Always use the fictional families provided, not real families."], rubric:[["1–2","Responsibilities are generic; no real comparison made."],["3–4","Basic responsibilities identified; comparison is vague."],["5–6","Clear, realistic responsibilities identified for both families; a reasonable comparison made."],["7–8","Thoughtful, realistic responsibilities identified; comparison is insightful and entirely respectful of both family structures."]]},
  game:{type:"sort", title:"Respectful Research Language", prompt:"Sort each statement: is it respectful and careful, or is it a stereotype that generalises?", bins:["Respectful and careful","Stereotype / over-generalising"], items:[["Many families expect older children to help care for younger siblings.",0],["All families in that country do exactly the same chores.",1],["In many Gulf and Arab cultures, caring for elderly parents is seen as an important duty.",0],["There is only one correct type of family.",1],["Family responsibilities can include emotional support and caring for relatives, not just chores.",0],["Responsibilities are usually age-appropriate and can change as children grow older.",0],["Every child in a culture has the same responsibilities, whatever their age.",1],["Families with a different structure from mine are doing it wrong.",1]]},
  quiz:[["What is a 'household'?",["A family or group of people living together in one home","A list of chores","A type of building"],0],["What does 'contribution' mean?",["A reward for doing chores","A rule set by parents","Something a person gives or does to help a shared effort"],2],["Which statement about family structures is correct?",["There is one correct family structure","Family structures are diverse, and responsibility applies within whatever family a person has","Only large families have responsibilities"],1],["Family responsibilities are…",["Only about chores","About chores, emotional support, caring for relatives and representing family values","Only for adults"],1],["In the extract, why is swapping with her brother a reasonable solution for Layla?",["Because the duty is still met by another family member","Because helping her grandmother does not matter","Because parties are more important than family"],0],["Which phrase is more respectful when describing a culture?",["“All families in X do Y”","“Nobody in X does Y”","“Many families in X do Y”"],2],["What does 'birr al-walidayn' refer to?",["A type of household chore","A school rule","Respect and care for parents"],2],["How do children's family responsibilities usually change?",["They stay exactly the same forever","They are usually age-appropriate and change as a person gets older","They disappear at age 10"],1]],
  exit:"Write ONE reason family responsibilities matter, using one Word Bank term.",
  copy:{facts:["Family responsibilities include household tasks, caring for younger or older relatives, emotional support and representing the family's values.","Family responsibilities can differ between families and cultures, and they are usually age-appropriate.","In UAE culture and Islamic values, family (usra) and duty to parents (birr al-walidayn) are core moral values."]},
  next:"Next lesson: we continue Unit 1 by exploring basic moral rules and why they matter."
 },
 {
  id:"l3", lesson:3, title:"Basic Moral Rules", unit:"Unit 1: Character & Morality", art:"rules",
  dna:"Recap: in one sentence, name one family responsibility from last lesson. Now think: imagine a world where nobody kept their promises. Write down ONE way this would make daily life harder.",
  dnaQs:["Name one family responsibility from last lesson.","Imagine a world where nobody kept their promises. Write ONE way this would make daily life harder."],
  dnaHint:"For the recap, you could say helping with household tasks or caring for a relative. For the promises question, a good answer explains that people could not trust or rely on each other — for example, plans with friends, borrowing things or teamwork would fall apart.",
  intentions:["Understand and name basic moral rules, such as not stealing, not lying, and keeping promises.","Explore why these basic moral rules matter for trust and cooperation.","Apply a moral rule to identify right and wrong in a scenario."],
  criteria:["I can name basic moral rules and justify why they matter.","I can explain why honesty, keeping promises and not stealing build trust.","I can identify which moral rule applies in a given scenario."],
  concept:{key:"Fairness", related:"Trust, Ethics", soi:"Shared moral rules create trust and enable cooperation within communities.", context:"Fairness and Development — exploring the rules and values that hold communities together.", uae:"UAE law and Islamic ethics both explicitly prohibit theft and dishonesty; links to Individuals & Societies (law and ethics)."},
  words:[["Moral rule","A widely shared guideline about right and wrong behaviour."],["Trust","A firm belief in the reliability or honesty of someone."],["Honesty","The quality of being truthful and sincere."],["Integrity","The quality of being honest and having strong moral principles."],["Promise","A declaration that one will do or not do something."],["Consequence","A result or effect of an action."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion A — Knowing and Understanding", steps:["Choose ONE basic moral rule (no stealing, no lying, or keeping promises).","Research how this rule appears across at least two different belief systems, cultures or legal systems.","Record: what you found, noting any similarities across the sources.","Note why you think this rule appears so widely across different societies."], prompts:["The moral rule I chose","How it appears in source 1 (belief system, culture or legal system)","How it appears in source 2, and any similarities","Why I think this rule appears so widely"], success:"Honesty and rules against theft appear across major world religions, most national legal systems, and secular ethical codes. Strong answers note that because these rules appear almost everywhere, they seem to serve a basic function (enabling trust and cooperation) rather than being random. For the top band, explain the rule across two contexts clearly, using two credible sources, with a thoughtful reason for why it is so widespread."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"Faisal borrowed his classmate's calculator and promised to return it the next day. The next day, he forgot and used it for another two days before returning it, without saying anything about the delay.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), identify which moral rule is relevant to Faisal's situation and explain why it matters.","Use at least THREE words from the Word Bank (e.g. trust, promise, consequence) accurately.","Suggest what Faisal should have done differently."], model:"Faisal's situation relates to the moral rule of keeping promises, because he told his classmate he would return the calculator the next day but did not. This matters because broken promises damage trust between people, even when the item itself is eventually returned. If Faisal wanted to keep the calculator longer, he should have contacted his classmate to explain and ask for more time, rather than staying silent, since honesty about the delay would have preserved trust even if the original promise had to change.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; suggestion is specific and well-justified."]], starters:["Faisal's situation relates to the moral rule of ___ because ___.","This matters because broken promises ___.","The consequence of Faisal's silence was ___.","Faisal should have ___ because ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Rules for Our Classroom", steps:["In groups of 3–4, propose THREE moral rules (beyond the three studied today) that would help your classroom function well.","For each rule, justify why it matters and what would happen if it were regularly broken.","Design your three rules as a simple classroom poster.","Identify one way to encourage the class to actually follow these rules (not just display them).","Present your rules to the class in a 3-minute pitch. Use Word Bank vocabulary in your presentation."], rubric:[["1–2","Rules are vague; little justification given."],["3–4","Basic rules with limited justification."],["5–6","Clear, sensible rules with reasonable justification for each."],["7–8","Well-justified, insightful rules; a genuinely practical idea for encouraging the class to follow them."]]},
  game:{type:"sort", title:"Which Moral Rule?", prompt:"Sort each situation under the basic moral rule it is about.", bins:["Do not steal","Do not lie","Keep your promises"], items:[["Taking a classmate's pen from their bag without asking",0],["Telling your teacher you did your homework when you did not",1],["Saying you will meet a friend at break, then not turning up",2],["Keeping extra money from a shop that is not yours",0],["Blaming your sibling for something you broke",1],["Returning a borrowed book on the day you said you would",2],["Copying a friend's answers and saying they are your own",1],["Agreeing to help with a group project and then doing your part",2]]},
  quiz:[["Which of these is one of the three basic moral rules in this lesson?",["Keep your promises","Always wear a uniform","Greet people in a certain way"],0],["Why do these basic moral rules matter?",["They make people famous","They are only school rules","They build trust and allow people to cooperate"],2],["What does 'integrity' mean?",["Being the strongest in the group","Being honest and having strong moral principles","Following fashion trends"],1],["Rules against lying and stealing appear…",["Only in one country","Across almost all societies, religions and legal systems","Only in schools"],1],["Which rule is most relevant to Faisal and the calculator?",["Keeping promises","Not stealing","Respecting elders"],0],["What should Faisal have done if he needed the calculator longer?",["Kept quiet and returned it later","Given it to someone else","Contacted his classmate to explain and ask for more time"],2],["Does breaking a small promise 'not count'?",["Correct, small promises don't matter","Only if a teacher finds out","It still counts, because trust is built through consistency, even in small things"],2],["How is a moral rule different from etiquette (manners)?",["They are exactly the same","Breaking a moral rule causes real harm; etiquette varies more between cultures","Etiquette is always more serious"],1]],
  exit:"Name one moral rule and explain, in one sentence, why breaking it damages trust.",
  copy:{facts:["Three basic moral rules: do not steal, do not lie, and keep your promises.","These rules appear across almost all societies, religions and legal systems because they build trust and cooperation.","UAE law and Islamic ethics both prohibit theft and dishonesty."]},
  next:"Next lesson: we continue Unit 1 by applying moral rules to real, sometimes tricky situations."
 },
 {
  id:"l4", lesson:4, title:"Applying Moral Rules — 'The Right Thing To Do'", unit:"Unit 1: Character & Morality", art:"applyrules",
  dna:"Recap: in one sentence, name one of the three basic moral rules from last lesson. Now think: you promised to help a friend after school, but your family unexpectedly needs you home right away. Write down what makes this situation tricky.",
  dnaQs:["Name one of the three basic moral rules from last lesson.","You promised to help a friend, but your family needs you home. What makes this tricky?"],
  dnaHint:"The three rules are: do not steal, do not lie, keep your promises. The situation is tricky because two things both matter — keeping your promise to your friend and your responsibility to your family — and they point in different directions.",
  intentions:["Apply basic moral rules to real, sometimes complicated situations.","Explore what to do when moral rules seem to conflict with each other.","Make and justify a moral decision using clear reasoning."],
  criteria:["I can apply a moral rule to a real situation.","I can explain what to consider when moral rules seem to conflict.","I can justify a moral decision with clear reasoning."],
  concept:{key:"Fairness", related:"Ethics, Consequences", soi:"Applying moral rules thoughtfully helps individuals make justified decisions, even in complicated situations.", context:"Fairness and Development — exploring how rules and values guide real decision-making.", uae:"Links to Individuals & Societies (ethics and law) and English (argumentative writing); builds directly on Lesson 3's moral rules."},
  words:[["Dilemma","A situation requiring a choice between two or more difficult options."],["Justify","To give good reasons for a decision or opinion."],["Conflict (of values)","A situation where two moral rules or values point in different directions."],["Consequence","A result or effect of a decision or action."],["Integrity","Acting consistently with one's stated moral principles."],["Decision","A conclusion reached after consideration of options."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion B — Investigating", steps:["Choose ONE age-appropriate real or realistic ethical dilemma (e.g. whistleblowing on a friend's mistake, honesty vs. loyalty).","Research it using at least one reliable source.","Record: which moral rules or values are in tension in this dilemma.","Note how the situation was resolved (if known), or how you think it should be resolved."], prompts:["The dilemma I chose and my source","The moral rules or values in tension","How it was resolved, or how I think it should be resolved"], success:"Good examples: a student deciding whether to report a friend's cheating (honesty vs. loyalty), a person deciding whether to return extra change given by mistake (honesty vs. self-interest), an employee deciding whether to report a colleague's small rule-breaking (honesty vs. workplace loyalty). Strong answers clearly name the two values in tension. For the top band, also propose a well-reasoned resolution."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"Maha promised to keep her friend's secret about a mistake at school. But she later learns the mistake might get someone else unfairly blamed if it stays hidden.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), identify the moral rules in conflict in Maha's situation.","Use at least THREE words from the Word Bank (e.g. dilemma, conflict, justify) accurately.","Decide and justify what Maha should do."], model:"Maha's situation involves a conflict between keeping a promise (loyalty to her friend) and preventing unfairness to someone else (honesty and fairness). This is a genuine dilemma because both values matter, but they point in different directions here. I think Maha should tell the truth, because preventing an innocent person from being unfairly blamed outweighs the promise, especially since the original promise was made without fully understanding the consequences. Her friend might be upset, but the greater harm of an innocent person being blamed justifies breaking the promise in this case. (Either conclusion — tell or don't tell — can earn full marks if the reasoning is well-justified.)", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; decision is well-justified with clear reasoning."]], starters:["Maha's situation involves a conflict between ___ and ___.","This is a genuine dilemma because ___.","I think Maha should ___ because ___.","The consequence of this decision would be ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Dilemma Court", steps:["In groups of 3–4, you will receive a dilemma card describing a values conflict.","Prepare arguments for TWO different possible responses to the dilemma.","Present both sides to the class as a mini 'court' — two group members argue each side.","As a class, vote on which response seems most justified, and discuss why.","Reflect: did hearing the other side change your view at all? Use Word Bank vocabulary in your arguments."], rubric:[["1–2","Arguments are one-sided or underdeveloped."],["3–4","Both sides presented with basic reasoning."],["5–6","Both sides presented with clear, relevant reasoning."],["7–8","Both sides presented with sophisticated, well-justified reasoning; genuine engagement with the opposing view."]]},
  game:{type:"sort", title:"Simple Choice or Real Dilemma?", prompt:"Sort each situation: is it a simple choice with a clear right answer, or a real dilemma where two important values conflict?", bins:["Simple choice","Real dilemma (values conflict)"], items:[["You find a wallet with an ID inside — should you keep the money?",0],["Your friend cheated on a test. Do you report it (honesty) or stay quiet (loyalty)?",1],["You promised to help a friend, but your family suddenly needs you at home.",1],["Should you copy a classmate's homework and hand it in as your own?",0],["You promised to keep a secret, but keeping it means someone else is unfairly blamed.",1],["A shop gives you too much change by mistake — do you return it?",0],["Your group is treating someone unfairly. Stay loyal to the group or speak up?",1]]},
  quiz:[["What is a dilemma?",["A situation requiring a choice between two or more difficult options","An easy decision","A type of rule"],0],["What does 'justify' mean?",["To change your mind","To ignore other views","To give good reasons for a decision or opinion"],2],["What is a 'conflict of values'?",["When two people have an argument about sport","When two moral rules or values point in different directions","When everyone agrees"],1],["Which two values are in tension in Maha's situation?",["Honesty and stealing","Keeping a promise (loyalty) and fairness to someone else","Family and school uniform"],1],["Do real moral dilemmas always have one clearly correct answer?",["No — some are genuinely contested, so the quality of your reasoning matters","Yes, always","Only if a teacher decides"],0],["Reporting a friend's cheating is an example of a conflict between…",["Food and water","Sport and music","Honesty and loyalty"],2],["If hearing the other side changes your mind, it means…",["You were wrong and should feel bad","You should never listen to others","You are thinking well and considering other perspectives"],2],["When deciding what to do in a dilemma, what should you consider?",["Only what is easiest for you","The values in conflict and the consequences of each choice","Whatever your friends say"],1]],
  exit:"Write ONE sentence about a time you (or someone you know) had to choose between two things that both felt important.",
  copy:{facts:["A dilemma is a situation where you must choose between difficult options, often because two values conflict.","Common conflicts include honesty vs. loyalty and keeping a promise vs. preventing unfairness.","Many dilemmas have no single 'correct' answer — what matters is justifying your decision with clear reasoning."]},
  next:"Next lesson: we continue Unit 1 by exploring basic human needs and why meeting them matters."
 },
 {
  id:"l5", lesson:5, title:"Basic Human Needs", unit:"Unit 1: Character & Morality", art:"needs",
  dna:"Recap: in one sentence, explain what a moral dilemma is. Now think: list THREE things every human being needs to survive and live with basic dignity, no matter where they live.",
  dnaQs:["In one sentence, what is a moral dilemma?","List THREE things every human being needs to survive and live with basic dignity."],
  dnaHint:"A moral dilemma is a situation where you must choose between difficult options, often because two values conflict. Basic human needs include food, clean water, shelter, safety and access to healthcare.",
  intentions:["Understand basic human needs and why meeting them is important.","Explore the link between unmet basic needs and conflict.","Evaluate why meeting basic needs matters for peaceful, stable communities."],
  criteria:["I can name basic human needs and explain their importance.","I can describe a link between unmet needs and conflict.","I can evaluate why meeting basic needs matters for peace and wellbeing."],
  concept:{key:"Systems", related:"Fairness, Conflict", soi:"Meeting basic human needs is essential for peaceful, stable communities.", context:"Fairness and Development — exploring the distribution of resources and its link to conflict and stability.", uae:"The UAE's significant role in international humanitarian aid, addressing unmet basic needs in crisis regions worldwide."},
  words:[["Need","Something a person requires in order to live and function with basic dignity."],["Deprivation","The state of lacking something considered a basic necessity."],["Conflict","A serious disagreement or struggle, sometimes involving violence."],["Stability","A state of being steady and not likely to change suddenly or violently."],["Resource","Something useful or valuable, such as food, water or shelter."],["Wellbeing","A state of being comfortable, healthy and content."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion B — Investigating", steps:["Choose ONE real humanitarian situation where unmet basic needs (food, water, shelter, safety) have contributed to instability or conflict.","Research it using at least two reliable sources (e.g. UN agencies, Red Crescent/Red Cross).","Record: what basic needs were unmet, and how this connected to instability.","Note one organisation working to address this situation, and what it does."], prompts:["The situation I chose and my two sources","The basic needs that were unmet","How this connected to instability or conflict","One organisation helping, and what it does"], success:"Good examples include humanitarian crises involving food or water insecurity, displacement due to conflict over resources, and refugee situations. Strong answers clearly connect a specific unmet need to a specific consequence (e.g. water scarcity contributing to disputes between communities) rather than making a vague general claim. For the top band, use two credible sources and identify a specific organisation and its response."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"In a region affected by prolonged drought, two neighbouring communities that once shared a water source begin to argue over access to what little remains.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), explain how the unmet need described could lead to conflict.","Use at least THREE words from the Word Bank (e.g. need, resource, stability) accurately.","Suggest one way the situation could be managed to reduce the risk of conflict."], model:"When a basic need like water becomes scarce, competition over the remaining resource can quickly turn into conflict, especially when communities feel their survival is at stake. In this situation, the drought has created deprivation, and the communities' stability is threatened as trust breaks down over access to a shared resource. To reduce the risk of conflict, an outside mediator or a fair, agreed water-sharing plan could help both communities meet their basic needs without resorting to confrontation.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; suggested management strategy is realistic."]], starters:["When a basic need like water becomes scarce, ___.","The drought has created deprivation, which ___.","The communities' stability is threatened because ___.","To reduce the risk of conflict, ___ could ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Basic Needs Aid Plan", steps:["In groups of 3–4, you are given a fictional community facing a shortage of one basic need (food, water, or shelter after a disaster).","Design an aid plan prioritising who receives help first and why, using fair, justified criteria.","Identify one practical challenge your plan would face (e.g. limited supplies, difficult access).","Propose how you would address that challenge.","Present your aid plan to the class in a 3-minute pitch. Use Word Bank vocabulary in your presentation."], rubric:[["1–2","Plan lacks clear prioritisation criteria; no challenge identified."],["3–4","Basic plan with limited justification; challenge named but not addressed."],["5–6","Clear plan with justified prioritisation criteria; challenge identified and addressed."],["7–8","Well-justified, realistic plan; prioritisation criteria and challenge response are thoughtful and convincing."]]},
  game:{type:"sort", title:"Need or Want?", prompt:"Sort each item: is it a basic human need for survival and dignity, or a want?", bins:["Basic human need","Want (nice to have)"], items:[["Clean drinking water",0],["Food",0],["Shelter",0],["Safety",0],["Access to healthcare",0],["The latest smartphone",1],["Designer trainers",1],["A games console",1]]},
  quiz:[["Which of these is a basic human need?",["Clean water","A games console","Designer clothes"],0],["What does 'deprivation' mean?",["Having too much food","A type of aid organisation","The state of lacking something considered a basic necessity"],2],["What does 'stability' mean?",["A sudden change","A state of being steady and not likely to change suddenly or violently","A serious disagreement"],1],["How can unmet basic needs lead to conflict?",["People stop needing water","People and groups compete for scarce resources","Everyone automatically shares more"],1],["In the extract, what is causing the two communities to argue?",["A prolonged drought making water scarce","A football match","A new school"],0],["Which is a realistic way to reduce the risk of conflict in the extract?",["Ignoring the problem","Letting the stronger community take all the water","A fair, agreed water-sharing plan or an outside mediator"],2],["Humanitarian aid that meets basic needs can also be described as…",["Something with no effect on peace","Only useful for wealthy countries","A form of conflict prevention, not just charity"],2],["How is the UAE connected to this lesson?",["It has no role in helping other countries","It plays a significant role in international humanitarian aid","It only helps its own citizens"],1]],
  exit:"Name one basic human need and explain, in one sentence, why meeting it supports peaceful communities.",
  copy:{facts:["Basic human needs include food, clean water, shelter, safety and access to healthcare.","When basic needs go unmet, competition over scarce resources can lead to tension, displacement and conflict.","Meeting basic needs through humanitarian aid helps prevent conflict — the UAE plays a significant role in global humanitarian aid."]},
  next:"Next lesson: we complete Unit 1 by exploring the fundamental value of every human life."
 },
 {
  id:"l6", lesson:6, title:"The Value of Every Human Life", unit:"Unit 1: Character & Morality", art:"life",
  dna:"Unit 1 vocabulary check! Match each term to its definition as fast as you can: Responsibility, Moral rule, Dilemma, Need, Integrity. This is our final lesson of Unit 1 — let's see how much has stuck.",
  dnaQs:["Responsibility and Moral rule — what does each mean?","Dilemma and Need — what does each mean?","Integrity — what does it mean?"],
  dnaHint:"Responsibility: a duty to deal with or take care of something or someone. Moral rule: a widely shared guideline about right and wrong behaviour. Dilemma: a situation requiring a choice between two or more difficult options. Need: something a person requires to live and function with basic dignity. Integrity: being honest and having strong moral principles.",
  intentions:["Understand and demonstrate commitment to the fundamental value of every human life.","Connect this value to responsibility, moral rules and human needs studied this unit.","Reflect on learning and personal growth across the whole of Unit 1."],
  criteria:["I can explain why every human life has fundamental value.","I can connect this idea to responsibility, rules and needs studied this unit.","I can reflect on my learning and growth across Unit 1."],
  concept:{key:"Fairness", related:"Ethics, Community", soi:"Recognising the fundamental value of every human life underpins responsible, moral and caring communities.", context:"Fairness and Development — exploring universal values that unite responsibility, rules and human needs.", uae:"Draws together UAE and Islamic values of human dignity, the UAE's humanitarian role (Lesson 5), and family/peer responsibility (Lessons 1–2)."},
  words:[["Human dignity","The inherent worth and respect that belongs to every person."],["Value (of life)","The fundamental importance and worth given to a human being."],["Compassion","Concern for the suffering of others, alongside a desire to help."],["Solidarity","Unity and mutual support within or between communities."],["Commitment","A dedication or pledge to a cause or value."],["Legacy","Something a unit of learning or a person's actions leave behind, going forward."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion A — Knowing and Understanding", steps:["Choose ONE real organisation whose work embodies valuing every human life (e.g. the Red Crescent/Red Cross, a UAE humanitarian foundation, a human rights organisation).","Research it using at least two reliable sources.","Record: what the organisation does, and how its work reflects the value of human life.","Note one specific example of its impact."], prompts:["The organisation I chose and my two sources","What the organisation does","How its work reflects the value of human life","One specific example of its impact"], success:"Good examples: the Red Crescent/Red Cross (humanitarian aid regardless of background), UAE-based humanitarian foundations, UNICEF (children's welfare globally). Strong answers cite a specific, real example of impact (a number, a programme, a place) rather than a vague description, and make a clear connection to valuing human life using two credible sources."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"Reflect on Unit 1: Lesson 1 (peer responsibility), Lesson 2 (family responsibility), Lesson 3 (moral rules), Lesson 4 (applying moral rules), and Lesson 5 (basic human needs).", steps:["Write a structured paragraph (topic sentence, three connections, conclusion) explaining how valuing every human life connects to what you learned in earlier lessons this unit.","Use at least FOUR words from across Unit 1's Word Bank (any lesson) accurately.","Conclude with one way this unit has changed or strengthened how you think about responsibility toward others."], model:"This unit has taught me that valuing every human life connects closely to the responsibilities we studied earlier: peer responsibility (Lesson 1) and family duty (Lesson 2) are both ways of showing that other people's wellbeing matters, moral rules like honesty and promise-keeping (Lesson 3) protect trust between people because each person's word and dignity matter, and meeting basic human needs (Lesson 5) is a direct expression of valuing every life equally. This unit has strengthened my understanding that morality isn't just about following rules, but about genuinely recognising the worth of every person I interact with, from a close family member to a stranger on the other side of the world.", rubric:[["1–2","Limited structure; little/no key vocabulary used; no real connections made."],["3–4","Basic paragraph structure; 1–2 key terms used; connections are vague."],["5–6","Clear paragraph structure; 3 key terms used mostly accurately; reasonable connections made."],["7–8","Well-structured paragraph; 4+ key terms used accurately across multiple lessons; connections are insightful and well-justified."]], starters:["This unit has taught me that valuing every human life connects to ___.","Peer and family responsibility show that ___.","Moral rules like honesty protect ___ because ___.","This unit has strengthened my understanding that ___."]},
  task3:{title:"Project Task (Unit Showcase)", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Our Class Values Charter", steps:["As a whole class, pool ideas from Task 1 research and Task 2 reflections.","In small groups, draft 2–3 concrete charter statements covering: responsibility (to peers and family), moral rules, and valuing every person.","As a class, agree on a final combined list of 6–8 statements for the class Values Charter.","Design the charter as a poster to be displayed in the classroom for the rest of the year.","Each student signs the charter as a personal commitment."], rubric:[["1–2","Charter statements are vague or generic; little connection to unit learning."],["3–4","Charter statements are basic but relevant; limited connection to specific unit ideas."],["5–6","Charter statements are specific and clearly connect to unit ideas (responsibility, rules, needs, value of life)."],["7–8","Charter statements are specific, practical and insightful; clear, well-justified connections across multiple unit lessons."]]},
  game:{type:"sort", title:"Which Lesson Does It Connect To?", prompt:"Sort each idea into the part of Unit 1 it comes from.", bins:["Responsibility (peers & family)","Moral rules & dilemmas","Basic human needs"], items:[["Inviting a new student to sit with your group",0],["Helping a grandmother with weekly shopping",0],["Keeping a promise to return a borrowed calculator",1],["Choosing between loyalty to a friend and fairness to someone else",1],["Never stealing or lying",1],["Making sure communities have clean water",2],["Providing food and shelter after a disaster",2],["Caring for younger siblings at home",0]]},
  quiz:[["What is 'human dignity'?",["The inherent worth and respect that belongs to every person","A reward for good behaviour","Respect only for important people"],0],["What does 'compassion' mean?",["Competing to be the best","Ignoring other people's problems","Concern for the suffering of others, alongside a desire to help"],2],["What does 'solidarity' mean?",["Working completely alone","Unity and mutual support within or between communities","A type of rule"],1],["The idea that every person has inherent dignity appears in…",["Only one religion","Major world religions, the UN Universal Declaration of Human Rights and secular ethics","No official documents"],1],["Valuing human life applies to…",["Everyone, from a close family member to a stranger far away","Only people we know and like","Only famous people"],0],["Valuing human life is…",["Only about avoiding extreme harm","Only a topic for adults","Also about everyday respect, inclusion and responsibility"],2],["How does meeting basic human needs (Lesson 5) connect to this lesson?",["It has nothing to do with valuing life","It only matters for animals","It is a direct expression of valuing every life equally"],2],["Once the class charter is made, the unit's values are…",["Finished and no longer needed","An ongoing practice to live out every day","Only for display"],1]],
  exit:"Write the ONE statement from our new class charter that you personally find most important, and why.",
  copy:{facts:["Every human life has fundamental value and dignity, whether the person is a close family member or a stranger far away.","Peer and family responsibility, moral rules, and meeting basic needs all rest on valuing every human life.","Human dignity is recognised across major world religions, the UN Universal Declaration of Human Rights and secular ethics."]},
  next:"Unit 1: Character & Morality is complete! Term 2 begins Unit 2: The Individual & the Community."
 }
];
